arguments.command:
cd /tmp/vally-eval-trial-TmKluM && mkdir -p tests/CheckoutPricing.UnitTests/LoyaltyDiscount && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier
{
    Gold,
}

public sealed record CalculatePayableTotalRequest(CustomerTier Tier, decimal Subtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalRequest request) => request.Subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/LoyaltyDiscount/GoldCustomerCheckoutTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class GoldCustomerCheckoutTests
{
    [Fact]
    public void Gold_customer_with_a_100_00_subtotal_pays_95_00()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalRequest(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -25

